// Insta Report intake bot — built file, do not edit.
// Generated by worker/build.mjs from worker/src/. Paste this whole file into
// the Cloudflare Worker editor; see worker/SETUP.md.

/* ---------- batch.js ---------- */

// A batch is one trip to a property: a project name, a running section, and the
// photos filed under it.
//
// Everything lives in KV, and the shape is chosen so the hot path never does a
// read-modify-write. Photos each get their own key, so two album items arriving
// at the same moment cannot overwrite one another — an append-only log that
// `/done` reads back with a prefix list. Only the small meta record is rewritten,
// and only by a command the user typed.
//
// Photo BYTES are never stored. Telegram already holds them and a file_id is
// permanent for the bot, so the batch carries identifiers and nothing heavier.

const CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';   // no I/L/O/0/1
const CODE_LEN = 8;
const TTL_DAYS = 14;
const TTL_SECONDS = TTL_DAYS * 86400;

const metaKey = (code) => `batch:${code}:meta`;
const photoKey = (code, id) => `batch:${code}:p:${String(id).padStart(12, '0')}`;
const chatKey = (chatId) => `chat:${chatId}`;

/** Codes are typed in by hand on a phone, so: no ambiguous glyphs, no vowels. */
function newCode() {
  const bytes = crypto.getRandomValues(new Uint8Array(CODE_LEN));
  return [...bytes].map((b) => CODE_ALPHABET[b % CODE_ALPHABET.length]).join('');
}

async function openBatch(env, chatId, projectName) {
  const code = newCode();
  const meta = {
    code,
    chatId,
    project: { name: (projectName || '').trim() },
    section: '',
    status: 'open',
    createdAt: Date.now(),
    closedAt: null,
    count: 0,
  };
  await putMeta(env, meta);
  await env.BATCHES.put(chatKey(chatId), code, { expirationTtl: TTL_SECONDS });
  return meta;
}

const putMeta = (env, meta) =>
  env.BATCHES.put(metaKey(meta.code), JSON.stringify(meta), { expirationTtl: TTL_SECONDS });

async function getMeta(env, code) {
  const raw = await env.BATCHES.get(metaKey(code));
  return raw ? JSON.parse(raw) : null;
}

/** The batch this chat is currently filing into, if any. */
async function activeBatch(env, chatId) {
  const code = await env.BATCHES.get(chatKey(chatId));
  if (!code) return null;
  const meta = await getMeta(env, code);
  return meta && meta.status === 'open' ? meta : null;
}

async function setSection(env, meta, title) {
  meta.section = String(title || '').trim().toUpperCase();
  await putMeta(env, meta);
  return meta;
}

/**
 * File one photo. `id` is the Telegram message_id, which also orders the batch:
 * album items can reach the webhook out of order, but their message ids do not
 * lie about the order they were sent in.
 */
async function addPhoto(env, meta, photo) {
  const rec = {
    id: photo.id,
    fileId: photo.fileId,
    section: meta.section || 'GENERAL',
    caption: photo.caption || '',
    takenAt: photo.takenAt,
    takenSource: photo.takenSource || 'telegram',
    w: photo.w || 0,
    h: photo.h || 0,
    mediaGroupId: photo.mediaGroupId || '',
    // Filled in later by the captioning pass; absent means "not looked at yet".
    aiCaption: undefined,
  };
  await env.BATCHES.put(photoKey(meta.code, rec.id), JSON.stringify(rec), { expirationTtl: TTL_SECONDS });
  return rec;
}

/** Every photo in the batch, in the order they were sent. */
async function listPhotos(env, code) {
  const out = [];
  let cursor;
  do {
    const page = await env.BATCHES.list({ prefix: `batch:${code}:p:`, cursor });
    for (const k of page.keys) {
      const raw = await env.BATCHES.get(k.name);
      if (raw) out.push(JSON.parse(raw));
    }
    cursor = page.list_complete ? null : page.cursor;
  } while (cursor);
  out.sort((a, b) => a.id - b.id);
  return out;
}

async function updatePhoto(env, code, id, patch) {
  const key = photoKey(code, id);
  const raw = await env.BATCHES.get(key);
  if (!raw) return null;
  const rec = { ...JSON.parse(raw), ...patch };
  await env.BATCHES.put(key, JSON.stringify(rec), { expirationTtl: TTL_SECONDS });
  return rec;
}

async function dropPhoto(env, code, id) {
  await env.BATCHES.delete(photoKey(code, id));
}

async function closeBatch(env, meta) {
  meta.status = 'closed';
  meta.closedAt = Date.now();
  await putMeta(env, meta);
  await env.BATCHES.delete(chatKey(meta.chatId));
  return meta;
}

async function deleteBatch(env, meta) {
  const photos = await listPhotos(env, meta.code);
  for (const p of photos) await env.BATCHES.delete(photoKey(meta.code, p.id));
  await env.BATCHES.delete(metaKey(meta.code));
  await env.BATCHES.delete(chatKey(meta.chatId));
}

/**
 * What the app downloads: sections in the order they were first used, each with
 * its photos. No bytes — every photo is fetched separately from /api/photo, so a
 * manifest stays a couple of kilobytes however big the day was.
 */
function manifest(meta, photos) {
  const order = [];
  const bySection = new Map();
  photos.forEach((p, i) => {
    const title = p.section || 'GENERAL';
    if (!bySection.has(title)) { bySection.set(title, []); order.push(title); }
    bySection.get(title).push({
      n: i + 1,
      id: p.id,
      caption: p.aiCaption || p.caption || '',
      captionSource: p.aiCaption ? 'ai' : (p.caption ? 'typed' : ''),
      takenAt: p.takenAt,
      takenSource: p.takenSource,
      w: p.w,
      h: p.h,
    });
  });
  return {
    format: 'instareport-intake',
    version: 1,
    code: meta.code,
    project: meta.project,
    status: meta.status,
    createdAt: meta.createdAt,
    closedAt: meta.closedAt,
    total: photos.length,
    pending: photos.filter((p) => p.aiCaption === undefined && !p.caption).length,
    sections: order.map((title) => ({ title, photos: bySection.get(title) })),
  };
}

/** Per-section counts, for the /list reply. */
function tally(photos) {
  const counts = new Map();
  for (const p of photos) counts.set(p.section, (counts.get(p.section) || 0) + 1);
  return [...counts.entries()];
}

const batch = { newCode, openBatch, getMeta, activeBatch, setSection, addPhoto, listPhotos, updatePhoto, dropPhoto, closeBatch, deleteBatch, manifest, tally, TTL_SECONDS, putMeta };

/* ---------- telegram.js ---------- */

// The slice of the Bot API this bot needs. Nothing here buffers a photo: the
// bytes go from Telegram to the app as a stream, which is what keeps the Worker
// inside the free plan's CPU budget.

const API = 'https://api.telegram.org';

async function call(env, method, body) {
  const res = await fetch(`${API}/bot${env.TG_TOKEN}/${method}`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  if (!data.ok) throw new Error(`${method} failed: ${data.description || res.status}`);
  return data.result;
}

const sendMessage = (env, chatId, text, extra = {}) =>
  call(env, 'sendMessage', { chat_id: chatId, text, ...extra });

const getFile = (env, fileId) => call(env, 'getFile', { file_id: fileId });

/**
 * Open the original bytes for a file_id. A file_path is short-lived, so it is
 * fetched fresh every time rather than cached; a file_id itself does not expire,
 * which is what lets Telegram be the photo store.
 */
async function openFile(env, fileId) {
  const file = await getFile(env, fileId);
  const res = await fetch(`${API}/file/bot${env.TG_TOKEN}/${file.file_path}`);
  if (!res.ok) throw new Error(`file download failed (${res.status})`);
  return res;
}

/** Post the manifest into the chat as a real file, for the fallback path. */
async function sendDocument(env, chatId, filename, text, caption) {
  const form = new FormData();
  form.set('chat_id', String(chatId));
  if (caption) form.set('caption', caption);
  // Blob + a filename argument rather than `new File`, which is not reliably a
  // global in the Workers runtime.
  form.append('document', new Blob([text], { type: 'application/json' }), filename);
  const res = await fetch(`${API}/bot${env.TG_TOKEN}/sendDocument`, { method: 'POST', body: form });
  const data = await res.json().catch(() => ({}));
  if (!data.ok) throw new Error(`sendDocument failed: ${data.description || res.status}`);
  return data.result;
}

/** Tell Telegram where to deliver updates. Saves the user a curl. */
const setWebhook = (env, url, secret) => call(env, 'setWebhook', {
  url,
  secret_token: secret,
  allowed_updates: ['message', 'channel_post'],
});

/** Who this token belongs to — used to confirm setup worked. */
const getMe = (env) => call(env, 'getMe', {});

/**
 * Pick the variant nearest a target width. Telegram ships several sizes of every
 * photo, so the right one for the model is already there — no resizing needed,
 * which a Worker could not afford to do anyway.
 */
function pickSize(sizes, targetPx) {
  if (!sizes || !sizes.length) return null;
  const sorted = [...sizes].sort((a, b) => a.width - b.width);
  return sorted.find((s) => s.width >= targetPx) || sorted[sorted.length - 1];
}

/** The largest variant, which is what the report should print. */
const largest = (sizes) =>
  (sizes && sizes.length ? [...sizes].sort((a, b) => b.width - a.width)[0] : null);

const tg = { openFile, sendDocument, pickSize, sendMessage, getFile, setWebhook, getMe, largest };

/* ---------- bot.js ---------- */

// What the site team sees. Every reply is one short line, because this is read
// one-handed, outdoors, on a phone.



const HELP = [
  'Insta Report intake',
  '',
  '/project 23 JALAN KERUING — start a new batch',
  '/sec KITCHEN — file the photos that follow under this section',
  '/list — what is in the batch so far',
  '/undo — remove the last photo',
  '/done — finish and get the import code',
  '/cancel — throw the batch away',
  '',
  'Forward photos here from the site group. The date they were originally sent',
  'is kept, so forwarding a week of work at once still files it by the right day.',
].join('\n');

/** Parse "/sec KITCHEN" or "/sec@mybot KITCHEN" into ['sec', 'KITCHEN']. */
function parseCommand(text) {
  const m = /^\/([a-z_]+)(?:@\w+)?(?:\s+([\s\S]*))?$/i.exec((text || '').trim());
  return m ? [m[1].toLowerCase(), (m[2] || '').trim()] : [null, ''];
}

async function handleUpdate(env, update, ctx) {
  const msg = update.message || update.channel_post;
  if (!msg) return;

  const chatId = msg.chat && msg.chat.id;
  if (!allowed(env, chatId)) return;                  // silence, not an error page

  if (msg.photo || msg.document) return filePhoto(env, msg, chatId, ctx);

  const [cmd, rest] = parseCommand(msg.text);
  if (!cmd) return;

  switch (cmd) {
    case 'start':
    case 'help':
      return tg.sendMessage(env, chatId, HELP);
    case 'project':
      return startProject(env, chatId, rest);
    case 'sec':
    case 'section':
      return chooseSection(env, chatId, rest);
    case 'list':
      return listBatch(env, chatId);
    case 'undo':
      return undo(env, chatId);
    case 'done':
      return done(env, chatId, ctx);
    case 'cancel':
      return cancel(env, chatId);
    default:
      return tg.sendMessage(env, chatId, `Unknown command. ${'/help'} for the list.`);
  }
}

/** An empty allowlist means "not configured yet" and accepts nothing. */
function allowed(env, chatId) {
  const list = String(env.ALLOWED_CHATS || '').split(',').map((s) => s.trim()).filter(Boolean);
  return list.length > 0 && list.includes(String(chatId));
}

async function startProject(env, chatId, name) {
  if (!name) return tg.sendMessage(env, chatId, 'Name it: /project 23 JALAN KERUING');
  const open = await batch.activeBatch(env, chatId);
  if (open) {
    return tg.sendMessage(env, chatId,
      `A batch for ${open.project.name || 'this chat'} is still open. /done it first, or /cancel.`);
  }
  const meta = await batch.openBatch(env, chatId, name);
  return tg.sendMessage(env, chatId,
    `Batch open — ${meta.project.name}\nNow: /sec CAR PORCH, then send the photos.`);
}

async function chooseSection(env, chatId, title) {
  const meta = await batch.activeBatch(env, chatId);
  if (!meta) return tg.sendMessage(env, chatId, 'No batch open. Start with /project <name>.');
  if (!title) return tg.sendMessage(env, chatId, 'Name it: /sec KITCHEN');
  await batch.setSection(env, meta, title);
  return tg.sendMessage(env, chatId, `Section: ${meta.section}`);
}

/**
 * File a photo against the batch's current section.
 *
 * Telegram re-encodes anything sent as a photo and drops its EXIF, so the send
 * time is the best capture time available and is marked as such. A photo sent as
 * a document keeps its original bytes — the import side reads EXIF out of those.
 */
async function filePhoto(env, msg, chatId, ctx) {
  const meta = await batch.activeBatch(env, chatId);
  if (!meta) return;                                  // chatter before /project: ignore

  const asDocument = !!(msg.document && /^image\//.test(msg.document.mime_type || ''));
  if (!msg.photo && !asDocument) return;              // a PDF or a voice note is not a defect

  const big = asDocument ? null : tg.largest(msg.photo);
  const rec = await batch.addPhoto(env, meta, {
    id: msg.message_id,
    fileId: asDocument ? msg.document.file_id : big.file_id,
    caption: (msg.caption || '').trim(),
    takenAt: sentAt(msg) * 1000,
    takenSource: asDocument ? 'file' : 'telegram',
    w: asDocument ? 0 : big.width,
    h: asDocument ? 0 : big.height,
    mediaGroupId: msg.media_group_id || '',
  });

  // Album items arrive as separate updates seconds apart; acking each one would
  // bury the chat, so only the first of a group speaks.
  if (rec.mediaGroupId && !firstOfGroup(rec, msg)) return;
  const photos = await batch.listPhotos(env, meta.code);
  const n = photos.filter((p) => p.section === rec.section).length;
  return tg.sendMessage(env, chatId, `✓ ${rec.section} · ${n}`,
    { disable_notification: true });
}

/**
 * When the photo was originally sent, not when it reached the bot. Photos are
 * forwarded from the site group in batches, so the forward time is just when
 * the office got round to it — a week of work would otherwise land on today.
 *
 * forward_origin is the current field and forward_date the older one; both are
 * read so this works whichever the Bot API sends. Nothing changes for a photo
 * sent to the bot directly.
 */
function sentAt(msg) {
  const origin = msg.forward_origin || {};
  return origin.date || msg.forward_date || msg.date || Math.floor(Date.now() / 1000);
}

// Telegram gives no "first of album" flag; the caption only rides on the first
// item, which is a good enough proxy and costs nothing to check.
const firstOfGroup = (rec, msg) => !!msg.caption || !rec.mediaGroupId;

async function listBatch(env, chatId) {
  const meta = await batch.activeBatch(env, chatId) || await lastClosed(env, chatId);
  if (!meta) return tg.sendMessage(env, chatId, 'No batch open. Start with /project <name>.');
  const photos = await batch.listPhotos(env, meta.code);
  if (!photos.length) return tg.sendMessage(env, chatId, `${meta.project.name} — no photos yet.`);
  const lines = batch.tally(photos).map(([sec, n]) => `${sec} — ${n}`);
  return tg.sendMessage(env, chatId,
    `${meta.project.name}\n${lines.join('\n')}\n${photos.length} photo(s) total.`);
}

async function undo(env, chatId) {
  const meta = await batch.activeBatch(env, chatId);
  if (!meta) return tg.sendMessage(env, chatId, 'No batch open.');
  const photos = await batch.listPhotos(env, meta.code);
  const last = photos[photos.length - 1];
  if (!last) return tg.sendMessage(env, chatId, 'Nothing to undo.');
  await batch.dropPhoto(env, meta.code, last.id);
  return tg.sendMessage(env, chatId, `Removed one from ${last.section}. ${photos.length - 1} left.`);
}

async function cancel(env, chatId) {
  const meta = await batch.activeBatch(env, chatId);
  if (!meta) return tg.sendMessage(env, chatId, 'No batch open.');
  await batch.deleteBatch(env, meta);
  return tg.sendMessage(env, chatId, 'Batch discarded.');
}

async function done(env, chatId, ctx) {
  const meta = await batch.activeBatch(env, chatId);
  if (!meta) return tg.sendMessage(env, chatId, 'No batch open.');
  const photos = await batch.listPhotos(env, meta.code);
  if (!photos.length) {
    await batch.deleteBatch(env, meta);
    return tg.sendMessage(env, chatId, 'Empty batch — discarded.');
  }
  await batch.closeBatch(env, meta);
  // So /list still answers after the batch is closed.
  await env.BATCHES.put(`chat:${chatId}:last`, meta.code, { expirationTtl: batch.TTL_SECONDS });

  const lines = batch.tally(photos).map(([sec, n]) => `${sec} — ${n}`);
  await tg.sendMessage(env, chatId, [
    `${meta.project.name} — done.`,
    ...lines,
    '',
    `Import code: ${meta.code}`,
    'Open Insta Report > + > Import from Telegram.',
  ].join('\n'));

  // The fallback: the same manifest as a file, for when typing a code is the
  // wrong shape of effort. It is metadata only, so it stays tiny.
  const doc = JSON.stringify(batch.manifest(meta, photos), null, 2);
  const send = tg.sendDocument(env, chatId, `${meta.code}.instareport.json`, doc,
    'Open this in Insta Report if you would rather not type the code.');
  if (ctx && ctx.waitUntil) ctx.waitUntil(send.catch(() => {}));
  else await send.catch(() => {});
}

/** /list after /done still answers, which is what someone checking would expect. */
async function lastClosed(env, chatId) {
  const code = await env.BATCHES.get(`chat:${chatId}:last`);
  return code ? batch.getMeta(env, code) : null;
}

/* ---------- index.js ---------- */

// Insta Report intake — the whole server side.
//
// It is a postbox, not a database: Telegram keeps the photo bytes, the app keeps
// the report, and this holds a few kilobytes of "which photo, which section"
// until the app collects them. That is what keeps it inside free plans with no
// payment method on the account — see worker/README.md.




const json = (data, status = 200) => new Response(JSON.stringify(data), {
  status,
  headers: { 'content-type': 'application/json', ...cors() },
});

// The app is served from GitHub Pages, so every API call is cross-origin.
const cors = () => ({
  'access-control-allow-origin': '*',
  'access-control-allow-headers': 'content-type',
  'access-control-allow-methods': 'GET,POST,OPTIONS',
});

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname.replace(/\/+$/, '') || '/';

    if (request.method === 'OPTIONS') return new Response(null, { headers: cors() });

    try {
      if (path === '/health') return json({ ok: true });

      if (path === '/tg/webhook' && request.method === 'POST') {
        // Telegram is the only caller that knows this header. Anything else is
        // someone poking at the URL.
        if (request.headers.get('x-telegram-bot-api-secret-token') !== env.TG_WEBHOOK_SECRET) {
          return json({ error: 'no' }, 401);
        }
        const update = await request.json();
        // Answer immediately and do the work after: Telegram retries an update
        // it thinks failed, which would file every photo twice.
        ctx.waitUntil(handleUpdate(env, update, ctx).catch((err) => console.error(err)));
        return json({ ok: true });
      }

      // Visited once, by hand, from a browser: it points Telegram at this very
      // Worker. The bot token stays here rather than going into a command line
      // or the address bar.
      if (path === '/tg/register') {
        if (url.searchParams.get('secret') !== env.TG_WEBHOOK_SECRET) {
          return json({ ok: false, error: 'That secret does not match TG_WEBHOOK_SECRET.' }, 401);
        }
        return register(env, url);
      }

      const manifestMatch = /^\/api\/batch\/([A-Z0-9]{4,16})$/.exec(path);
      if (manifestMatch) return serveManifest(env, manifestMatch[1]);

      const photoMatch = /^\/api\/photo\/([A-Z0-9]{4,16})\/(\d+)$/.exec(path);
      if (photoMatch) return servePhoto(env, photoMatch[1], Number(photoMatch[2]));

      const claimMatch = /^\/api\/batch\/([A-Z0-9]{4,16})\/claim$/.exec(path);
      if (claimMatch && request.method === 'POST') return claim(env, claimMatch[1]);

      return json({ error: 'not found' }, 404);
    } catch (err) {
      console.error(err);
      return json({ error: 'server error' }, 500);
    }
  },
};

/**
 * Point Telegram at this Worker. This is the one step done by hand during
 * setup, so it says exactly what is wrong rather than falling into the generic
 * 500 — it is already behind the secret, so there is nothing to hide here.
 */
async function register(env, url) {
  const token = String(env.TG_TOKEN || '').trim();
  const secret = String(env.TG_WEBHOOK_SECRET || '');

  if (!token) {
    return json({ ok: false, error: 'TG_TOKEN is not set. Add it in the Worker\u2019s '
      + 'Settings > Variables and Secrets, as a Secret, then Deploy and try again.' }, 400);
  }

  // Deliberately no local check of what a token or a secret should look like.
  // Telegram is the authority on its own credentials, and a guess at the format
  // here would sit between the user and a perfectly good token. Ask Telegram,
  // and if it says no, describe what is stored so the bad paste is visible.
  const hook = `${url.origin}/tg/webhook`;
  try {
    await tg.setWebhook(env, hook, secret);
  } catch (err) {
    return json({
      ok: false,
      error: `Telegram refused: ${err.message}`,
      webhook: hook,
      check: describe(token, secret),
      hint: hintFor(err.message, token, secret),
    }, 502);
  }
  const me = await tg.getMe(env).catch(() => ({}));
  return json({ ok: true, bot: me.username || null, webhook: hook });
}

/**
 * The shape of the stored values, never the values themselves. Enough to spot a
 * paste that picked up a label, a quote, a line break or an invisible
 * character — safe to paste into a chat when asking for help.
 */
function describe(token, secret) {
  const colon = token.indexOf(':');
  const common = (v) => ({
    length: v.length,
    hasWhitespace: /\s/.test(v),
    hasQuotes: /['"]/.test(v),
    nonAscii: /[^\x20-\x7E]/.test(v),
  });
  return {
    TG_TOKEN: {
      ...common(token),
      hasColon: colon > 0,
      digitsBeforeColon: colon > 0 && /^\d+$/.test(token.slice(0, colon)),
      charsAfterColon: colon > 0 ? token.length - colon - 1 : 0,
    },
    TG_WEBHOOK_SECRET: {
      ...common(secret),
      // Telegram only accepts these in a secret_token.
      onlyLettersNumbersDashUnderscore: /^[A-Za-z0-9_-]{1,256}$/.test(secret),
    },
  };
}

/** Turn the common failures into the actual next action. */
function hintFor(message, token, secret) {
  if (/secret_token/i.test(message)) {
    return 'Change TG_WEBHOOK_SECRET to letters, numbers, underscore and hyphen only, '
      + 'Deploy, then visit this address again with the new value.';
  }
  if (/unauthorized|not found/i.test(message)) {
    if (!/^\d+:/.test(token)) {
      return 'What is stored in TG_TOKEN does not start with digits and a colon, so it is '
        + 'probably not the token — check you did not swap it with another value, or paste a '
        + 'label like "TG_TOKEN=" along with it.';
    }
    return 'The token is the right shape but Telegram does not recognise it. Re-copy it from '
      + 'BotFather (/mybots > your bot > API Token), replace TG_TOKEN, and Deploy.';
  }
  if (/url/i.test(message)) {
    return 'Telegram could not accept this Worker address. It must be public https, which a '
      + 'workers.dev address is — check the Worker is deployed.';
  }
  return 'Send me the whole of this reply; it carries no secret values.';
}

async function serveManifest(env, code) {
  const meta = await batch.getMeta(env, code);
  if (!meta) return json({ error: 'unknown code' }, 404);
  const photos = await batch.listPhotos(env, code);
  return json(batch.manifest(meta, photos));
}

/**
 * Stream one photo straight from Telegram to the app. Nothing is buffered and
 * nothing is re-encoded, so a 4MB photo costs the same CPU as a 40KB one.
 */
async function servePhoto(env, code, id) {
  const meta = await batch.getMeta(env, code);
  if (!meta) return json({ error: 'unknown code' }, 404);
  const photos = await batch.listPhotos(env, code);
  const photo = photos.find((p) => p.id === id);
  if (!photo) return json({ error: 'unknown photo' }, 404);

  const upstream = await tg.openFile(env, photo.fileId);
  return new Response(upstream.body, {
    headers: {
      'content-type': upstream.headers.get('content-type') || 'image/jpeg',
      'cache-control': 'private, max-age=3600',
      ...cors(),
    },
  });
}

/** The app has the photos now, so the batch can go. */
async function claim(env, code) {
  const meta = await batch.getMeta(env, code);
  if (!meta) return json({ error: 'unknown code' }, 404);
  await batch.deleteBatch(env, meta);
  return json({ ok: true });
}

